struct ChainLoad<'a> {
    inputs: Option<&'a CompilerInputs>,
    active: FxHashSet<PathBuf>,
    completed: FxHashMap<PathBuf, Map<std::string::String, Value>>,
    cycle_cut: bool,
    dependencies: Option<Vec<PathBuf>>,
}

impl VirtualProject {
