        if options.get("target").and_then(Value::as_str) != Some("auto") {
            return None;
        }
        let directory = config.parent().unwrap_or(&self.project_root);
        inputs
            .map_or_else(
                || crate::package_route::installed_package_manifest(directory, "vue"),
